import sys

def read(f):
	(n, x, y) = map(int, f.readline().split())
	a = f.readline().strip()
	b = f.readline().strip()
	zs = [i for (i, (c, d)) in enumerate(zip(a, b)) if c != d]
	return (zs, x, y)

def solve():
	(zs, x, y) = read(sys.stdin)
	if len(zs) % 2 != 0:
		print(-1)
		return
	if len(zs) == 0:
		print(0)
		return
	if x >= y:
		if len(zs) == 2 and zs[0] + 1 == zs[1]:
			print(min(x, 2 * y))
		else:
			print(len(zs) // 2 * y)
	else:
		f = []
		for (i, z) in enumerate(zs):
			if i == 0:
				cur = y
			elif i == 1:
				cur = min(2 * y, 2 * x * (z - zs[0]))
			else:
				cur = min(2 * x * (z - zs[i - 1]) + f[i - 2], y + f[i - 1])
			f.append(cur)
		print(f[-1] // 2)

def main():
	T = int(input().strip())
	for t in range(1, T + 1):
		solve()
main()
